def transform(grid):
    # A nonzero input cell expands to the color's 3x3 mark.
    motif=[[3,3,0],[0,0,3],[3,3,0]]
    out=[[0]*9 for _ in range(9)]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                for i in range(3):
                    for j in range(3):
                        if motif[i][j]: out[r*3+i][c*3+j]=v
    return out
